 'zh-Hant':'媒體表面|地圖媒體表面|放置表面…|地圖尚無媒體表面。|屬於此地圖的圖片與影片。儲存地圖以保留變更。|點擊地圖放置 · Esc 取消|此表面 ID 已在地圖中使用。|Ctrl＋右鍵拖曳：環顧。WASD：移動。Q/E：下降／上升。',
