  "ja": "アクター：{name}|敵：{name}|パーティ枠 {n}|敵 {n}|存在しないシーケンス #{id}|ルームイベント：{name}|敵グループのページに呼び出しを追加：{name}|使用先：{records}|プレビューを読み込めませんでした：{error}|{frame} / {duration} フレーム · {seconds}秒|シーケンスには最大256ステップまで追加できます。",
