// Behaviour forecast panel under the enemy Action Patterns table.
{
 const keys=["Behaviour forecast", "{n} of {total} unreachable", "Every action can fire", "Too many combinations to check.", "Rating ceiling", "Never fires", "No action can be chosen here.", "Only the highest valid rating is ever chosen.", "Only ratings within {n} of the highest valid rating are ever chosen.", "Battle AI picks at random, ignoring ratings.", "Battle AI uses gambit order: the first valid action wins.", "The skill no longer exists.", "This skill cannot be used in battle.", "The cost is higher than this enemy can hold.", "These conditions can never hold together.", "Outranked whenever it is usable: the ceiling never drops below {n}.", "Plugins can add conditions this panel cannot see."];
 const rows={
  "ja": "行動予測|{total} 件中 {n} 件が到達不能|すべての行動が発動可能|組み合わせが多すぎて確認できません。|レーティング上限|発動しない行動|この状況では行動を選択できません。|有効な行動のうち最高レーティングのみが選ばれます。|最高レーティングから {n} 以内の行動のみが選ばれます。|バトルAIはレーティングを無視してランダムに選びます。|バトルAIはガンビット順で、最初に条件を満たした行動を選びます。|スキルが存在しません。|このスキルは戦闘中に使用できません。|コストがこの敵の最大値を超えています。|これらの条件は同時に成立しません。|使用可能なときは常に上位に負けます: レーティング上限が {n} を下回りません。|プラグインが追加した条件はこのパネルでは判定できません。",
  "es": "Previsión de comportamiento|{n} de {total} inalcanzables|Todas las acciones pueden usarse|Demasiadas combinaciones para comprobar.|Techo de rating|Nunca se usa|Aquí no puede elegirse ninguna acción.|Solo se elige el rating válido más alto.|Solo se eligen los ratings dentro de {n} del rating válido más alto.|La IA de combate elige al azar, ignorando el rating.|La IA de combate usa orden de gambito: gana la primera acción válida.|La habilidad ya no existe.|Esta habilidad no puede usarse en combate.|El coste supera lo que este enemigo puede tener.|Estas condiciones nunca se cumplen a la vez.|Superada siempre que es usable: el techo nunca baja de {n}.|Los plugins pueden añadir condiciones que este panel no ve.",
  "zh-Hant": "行動預測|{total} 個中有 {n} 個無法觸發|所有行動都能觸發|組合過多，無法檢查。|評級上限|永不觸發|此情況下無法選擇任何行動。|只會選擇有效行動中評級最高者。|只會選擇與最高有效評級相差 {n} 以內的行動。|戰鬥AI隨機選擇，忽略評級。|戰鬥AI採用甘比特順序：第一個符合條件的行動勝出。|該技能已不存在。|此技能無法在戰鬥中使用。|消耗高於此敵人所能擁有的上限。|這些條件永遠無法同時成立。|可用時總是被壓過：評級上限從不低於 {n}。|外掛可能加入此面板看不到的條件。",
  "zh-Hans": "行动预测|{total} 个中有 {n} 个无法触发|所有行动都能触发|组合过多，无法检查。|评级上限|永不触发|此情况下无法选择任何行动。|只会选择有效行动中评级最高者。|只会选择与最高有效评级相差 {n} 以内的行动。|战斗AI随机选择，忽略评级。|战斗AI采用甘比特顺序：第一个符合条件的行动胜出。|该技能已不存在。|此技能无法在战斗中使用。|消耗高于此敌人所能拥有的上限。|这些条件永远无法同时成立。|可用时总是被压过：评级上限从不低于 {n}。|插件可能加入此面板看不到的条件。",
  "ru": "Прогноз поведения|{n} из {total} недостижимы|Все действия могут сработать|Слишком много сочетаний для проверки.|Потолок рейтинга|Никогда не срабатывает|В этой ситуации нельзя выбрать ни одно действие.|Выбирается только наивысший доступный рейтинг.|Выбираются только рейтинги в пределах {n} от наивысшего доступного.|Боевой ИИ выбирает случайно, игнорируя рейтинг.|Боевой ИИ использует порядок гамбита: побеждает первое доступное действие.|Навык больше не существует.|Этот навык нельзя использовать в бою.|Стоимость выше того, что может накопить этот враг.|Эти условия никогда не выполняются одновременно.|Проигрывает всегда, когда доступно: потолок не опускается ниже {n}.|Плагины могут добавлять условия, невидимые для этой панели.",
  "pt": "Previsão de comportamento|{n} de {total} inalcançáveis|Todas as ações podem ser usadas|Combinações demais para verificar.|Teto de rating|Nunca é usada|Nenhuma ação pode ser escolhida aqui.|Só o maior rating válido é escolhido.|Só ratings dentro de {n} do maior rating válido são escolhidos.|A IA de batalha escolhe ao acaso, ignorando o rating.|A IA de batalha usa ordem de gambito: a primeira ação válida vence.|A habilidade não existe mais.|Esta habilidade não pode ser usada em batalha.|O custo é maior do que este inimigo pode ter.|Estas condições nunca valem ao mesmo tempo.|Superada sempre que é utilizável: o teto nunca cai abaixo de {n}.|Plugins podem adicionar condições que este painel não vê.",
  "de": "Verhaltensprognose|{n} von {total} unerreichbar|Alle Aktionen können eingesetzt werden|Zu viele Kombinationen zum Prüfen.|Bewertungsgrenze|Wird nie eingesetzt|Hier kann keine Aktion gewählt werden.|Nur die höchste gültige Bewertung wird gewählt.|Nur Bewertungen innerhalb von {n} zur höchsten gültigen werden gewählt.|Die Kampf-KI wählt zufällig und ignoriert Bewertungen.|Die Kampf-KI nutzt Gambit-Reihenfolge: die erste gültige Aktion gewinnt.|Die Fähigkeit existiert nicht mehr.|Diese Fähigkeit ist im Kampf nicht einsetzbar.|Die Kosten übersteigen, was dieser Gegner halten kann.|Diese Bedingungen können nie zugleich gelten.|Wird immer überboten, wenn einsetzbar: die Grenze fällt nie unter {n}.|Plugins können Bedingungen ergänzen, die dieses Panel nicht sieht.",
  "fr": "Prévision de comportement|{n} sur {total} inatteignables|Toutes les actions peuvent se déclencher|Trop de combinaisons à vérifier.|Plafond de notation|Ne se déclenche jamais|Aucune action ne peut être choisie ici.|Seule la note valide la plus haute est choisie.|Seules les notes à moins de {n} de la plus haute note valide sont choisies.|L'IA de combat choisit au hasard, en ignorant les notes.|L'IA de combat suit l'ordre gambit : la première action valide l'emporte.|La compétence n'existe plus.|Cette compétence ne peut pas servir en combat.|Le coût dépasse ce que cet ennemi peut détenir.|Ces conditions ne peuvent jamais être vraies ensemble.|Surclassée dès qu'elle est utilisable : le plafond ne descend jamais sous {n}.|Les plugins peuvent ajouter des conditions invisibles pour ce panneau.",
  "el": "Πρόβλεψη συμπεριφοράς|{n} από {total} μη προσβάσιμες|Όλες οι ενέργειες μπορούν να χρησιμοποιηθούν|Πάρα πολλοί συνδυασμοί για έλεγχο.|Ανώτατη βαθμολογία|Δεν χρησιμοποιείται ποτέ|Εδώ δεν μπορεί να επιλεγεί καμία ενέργεια.|Επιλέγεται μόνο η υψηλότερη έγκυρη βαθμολογία.|Επιλέγονται μόνο βαθμολογίες έως {n} κάτω από την υψηλότερη έγκυρη.|Η ΤΝ μάχης επιλέγει τυχαία, αγνοώντας τις βαθμολογίες.|Η ΤΝ μάχης χρησιμοποιεί σειρά gambit: κερδίζει η πρώτη έγκυρη ενέργεια.|Η ικανότητα δεν υπάρχει πλέον.|Αυτή η ικανότητα δεν χρησιμοποιείται σε μάχη.|Το κόστος ξεπερνά όσα μπορεί να έχει αυτός ο εχθρός.|Αυτές οι συνθήκες δεν ισχύουν ποτέ ταυτόχρονα.|Χάνει όποτε είναι διαθέσιμη: το ανώτατο δεν πέφτει ποτέ κάτω από {n}.|Τα πρόσθετα μπορούν να προσθέσουν συνθήκες που δεν βλέπει αυτό το πλαίσιο.",
  "ko": "행동 예측|{total}개 중 {n}개 도달 불가|모든 행동이 발동 가능|조합이 너무 많아 확인할 수 없습니다.|레이팅 상한|발동하지 않음|이 상황에서는 행동을 선택할 수 없습니다.|유효한 행동 중 최고 레이팅만 선택됩니다.|최고 유효 레이팅에서 {n} 이내인 것만 선택됩니다.|전투 AI가 레이팅을 무시하고 무작위로 선택합니다.|전투 AI가 갬빗 순서를 사용합니다: 첫 번째 유효 행동이 선택됩니다.|스킬이 더 이상 존재하지 않습니다.|이 스킬은 전투에서 사용할 수 없습니다.|소비가 이 적이 가질 수 있는 최대치를 넘습니다.|이 조건들은 동시에 성립할 수 없습니다.|사용 가능할 때 항상 밀립니다: 상한이 {n} 아래로 내려가지 않습니다.|플러그인이 이 패널에서 볼 수 없는 조건을 추가할 수 있습니다.",
  "ar": "توقع السلوك|{n} من {total} غير قابلة للتنفيذ|جميع الإجراءات يمكن استخدامها|عدد التركيبات أكبر من أن يُفحص.|سقف التقييم|لا تُستخدم أبدًا|لا يمكن اختيار أي إجراء هنا.|يُختار أعلى تقييم صالح فقط.|تُختار التقييمات ضمن {n} من أعلى تقييم صالح فقط.|ذكاء المعركة يختار عشوائيًا متجاهلًا التقييم.|ذكاء المعركة يستخدم ترتيب الغامبيت: يفوز أول إجراء صالح.|المهارة لم تعد موجودة.|لا يمكن استخدام هذه المهارة في المعركة.|التكلفة أعلى مما يستطيع هذا العدو امتلاكه.|هذه الشروط لا تتحقق معًا أبدًا.|تُتجاوز كلما كانت قابلة للاستخدام: السقف لا ينزل عن {n}.|قد تضيف الإضافات شروطًا لا تراها هذه اللوحة.",
  "it": "Previsione di comportamento|{n} su {total} irraggiungibili|Tutte le azioni possono essere usate|Troppe combinazioni da controllare.|Tetto di valutazione|Non viene mai usata|Qui non può essere scelta alcuna azione.|Viene scelta solo la valutazione valida più alta.|Vengono scelte solo le valutazioni entro {n} dalla più alta valida.|L'IA di battaglia sceglie a caso, ignorando le valutazioni.|L'IA di battaglia usa l'ordine gambit: vince la prima azione valida.|L'abilità non esiste più.|Questa abilità non è utilizzabile in battaglia.|Il costo supera quanto questo nemico può avere.|Queste condizioni non valgono mai insieme.|Superata ogni volta che è utilizzabile: il tetto non scende mai sotto {n}.|I plugin possono aggiungere condizioni che questo pannello non vede.",
  "pl": "Prognoza zachowania|{n} z {total} nieosiągalnych|Wszystkie akcje mogą się uruchomić|Zbyt wiele kombinacji do sprawdzenia.|Pułap oceny|Nigdy się nie uruchamia|Tutaj nie można wybrać żadnej akcji.|Wybierana jest tylko najwyższa dostępna ocena.|Wybierane są tylko oceny w granicach {n} od najwyższej dostępnej.|SI walki wybiera losowo, ignorując oceny.|SI walki używa kolejności gambitu: wygrywa pierwsza dostępna akcja.|Umiejętność już nie istnieje.|Tej umiejętności nie można użyć w walce.|Koszt przekracza to, co ten wróg może posiadać.|Te warunki nigdy nie zachodzą jednocześnie.|Przegrywa zawsze, gdy jest dostępna: pułap nie spada poniżej {n}.|Wtyczki mogą dodać warunki niewidoczne dla tego panelu.",
  "id": "Prakiraan perilaku|{n} dari {total} tidak terjangkau|Semua aksi dapat dipakai|Terlalu banyak kombinasi untuk diperiksa.|Batas atas rating|Tidak pernah dipakai|Tidak ada aksi yang bisa dipilih di sini.|Hanya rating valid tertinggi yang dipilih.|Hanya rating dalam jarak {n} dari rating valid tertinggi yang dipilih.|AI pertarungan memilih acak, mengabaikan rating.|AI pertarungan memakai urutan gambit: aksi valid pertama yang menang.|Skill sudah tidak ada.|Skill ini tidak dapat dipakai dalam pertarungan.|Biayanya melebihi yang bisa dimiliki musuh ini.|Kondisi ini tidak pernah terpenuhi bersamaan.|Selalu kalah saat dapat dipakai: batas atas tidak pernah turun di bawah {n}.|Plugin dapat menambah kondisi yang tidak terlihat panel ini.",
  "vi": "Dự đoán hành vi|{n} trên {total} không thể xảy ra|Mọi hành động đều có thể được dùng|Quá nhiều tổ hợp để kiểm tra.|Trần xếp hạng|Không bao giờ được dùng|Không thể chọn hành động nào ở đây.|Chỉ xếp hạng hợp lệ cao nhất được chọn.|Chỉ những xếp hạng trong khoảng {n} so với cao nhất được chọn.|AI chiến đấu chọn ngẫu nhiên, bỏ qua xếp hạng.|AI chiến đấu dùng thứ tự gambit: hành động hợp lệ đầu tiên thắng.|Kỹ năng không còn tồn tại.|Kỹ năng này không dùng được trong chiến đấu.|Chi phí cao hơn mức kẻ địch này có thể có.|Các điều kiện này không bao giờ cùng đúng.|Luôn bị vượt khi dùng được: trần không bao giờ xuống dưới {n}.|Plugin có thể thêm điều kiện mà bảng này không thấy.",
  "th": "การคาดการณ์พฤติกรรม|{n} จาก {total} เข้าไม่ถึง|ทุกแอ็กชันสามารถถูกใช้ได้|มีชุดค่าผสมมากเกินกว่าจะตรวจสอบ|เพดานเรตติ้ง|ไม่เคยถูกใช้|ไม่มีแอ็กชันใดถูกเลือกได้ในสถานการณ์นี้|เลือกเฉพาะเรตติ้งสูงสุดที่ใช้ได้เท่านั้น|เลือกเฉพาะเรตติ้งที่ห่างจากสูงสุดไม่เกิน {n} เท่านั้น|AI การต่อสู้เลือกแบบสุ่มโดยไม่สนใจเรตติ้ง|AI การต่อสู้ใช้ลำดับแกมบิต: แอ็กชันที่ใช้ได้อันแรกชนะ|ไม่พบสกิลนี้แล้ว|สกิลนี้ใช้ในการต่อสู้ไม่ได้|ค่าใช้จ่ายสูงกว่าที่ศัตรูตัวนี้จะมีได้|เงื่อนไขเหล่านี้ไม่มีทางเป็นจริงพร้อมกัน|แพ้เสมอเมื่อใช้ได้: เพดานไม่เคยต่ำกว่า {n}|ปลั๊กอินอาจเพิ่มเงื่อนไขที่แผงนี้มองไม่เห็น",
  "tr": "Davranış tahmini|{total} eylemden {n} tanesi erişilemez|Tüm eylemler kullanılabilir|Kontrol edilemeyecek kadar çok kombinasyon var.|Derece tavanı|Hiç kullanılmaz|Burada hiçbir eylem seçilemez.|Yalnızca geçerli en yüksek derece seçilir.|Yalnızca en yüksek geçerli dereceden {n} içindeki dereceler seçilir.|Savaş YZ'si dereceleri yok sayarak rastgele seçer.|Savaş YZ'si gambit sırası kullanır: ilk geçerli eylem kazanır.|Beceri artık mevcut değil.|Bu beceri savaşta kullanılamaz.|Maliyet bu düşmanın tutabileceğinden yüksek.|Bu koşullar asla aynı anda sağlanmaz.|Kullanılabilir olduğu her an geçilir: tavan {n} altına hiç inmez.|Eklentiler bu panelin göremediği koşullar ekleyebilir."
 };
 for(const [locale,row] of Object.entries(rows)){const values=row.split('|');keys.forEach((key,i)=>globalThis.RR_REVIEWED_TRANSLATIONS.text[locale][key]=values[i]);}
}

// Battle AI on-the-spot turn counting, noted on the behaviour forecast panel.
{
 const keys=["Battle AI counts turns on the spot, so a turn condition can sit one turn earlier than it reads."];
 const rows={
  "ja": "バトルAIはその場でターンを数えるため、ターン条件が表示より1ターン早く成立することがあります。",
  "es": "La IA de combate cuenta los turnos sobre la marcha, así que una condición de turno puede cumplirse un turno antes de lo que indica.",
  "zh-Hant": "戰鬥AI即時計算回合，因此回合條件可能比顯示的早一個回合成立。",
  "zh-Hans": "战斗AI即时计算回合，因此回合条件可能比显示的早一个回合成立。",
  "ru": "Боевой ИИ считает ходы на месте, поэтому условие хода может выполниться на ход раньше, чем указано.",
  "pt": "A IA de batalha conta os turnos na hora, então uma condição de turno pode valer um turno antes do indicado.",
  "de": "Die Kampf-KI zählt Runden sofort, daher kann eine Rundenbedingung eine Runde früher greifen als angegeben.",
  "fr": "L’IA de combat compte les tours sur le moment, donc une condition de tour peut se réaliser un tour plus tôt qu’indiqué.",
  "el": "Η ΤΝ μάχης μετρά τους γύρους επιτόπου, οπότε μια συνθήκη γύρου μπορεί να ισχύσει έναν γύρο νωρίτερα από ό,τι δείχνει.",
  "ko": "전투 AI는 턴을 즉석에서 세므로, 턴 조건이 표시보다 한 턴 빠르게 성립할 수 있습니다.",
  "ar": "يحسب ذكاء المعركة الأدوار في حينها، لذا قد يتحقق شرط الدور قبل المعروض بدور واحد.",
  "it": "L’IA di battaglia conta i turni sul momento, quindi una condizione di turno può valere un turno prima di quanto indicato.",
  "pl": "SI walki liczy tury na bieżąco, więc warunek tury może zajść o turę wcześniej, niż wskazuje.",
  "id": "AI pertarungan menghitung giliran saat itu juga, jadi kondisi giliran bisa terpenuhi satu giliran lebih awal.",
  "vi": "AI chiến đấu đếm lượt ngay tại chỗ, nên điều kiện lượt có thể đúng sớm hơn một lượt so với hiển thị.",
  "th": "AI การต่อสู้นับเทิร์นทันที เงื่อนไขเทิร์นจึงอาจเป็นจริงเร็วกว่าที่แสดงหนึ่งเทิร์น",
  "tr": "Savaş YZ’si turları anında sayar, bu yüzden bir tur koşulu göründüğünden bir tur önce geçerli olabilir."
 };
 for(const [locale,row] of Object.entries(rows)){const values=row.split('|');keys.forEach((key,i)=>globalThis.RR_REVIEWED_TRANSLATIONS.text[locale][key]=values[i]);}
}

