  "Align Y:": "对齐 Y：",
  "All Categories": "全部分类",
  "All available plugins are already added!": "所有可用插件均已添加！",
  "Alpha multiplier applied to textured faces. 1 = opaque, 0 = invisible. Lets you fade the texture for ghost / holographic looks.": "应用于贴图面的透明度倍率。1 = 不透明，0 = 不可见。可让贴图淡出，实现幽灵/全息效果。",
  "Alpha multiplier applied to the textured faces. 1 = opaque (wireframe hidden); 0 = invisible (wireframe only); in between = both visible.": "应用于贴图面的透明度倍率。1 = 不透明（隐藏线框）；0 = 不可见（仅线框）；介于两者之间 = 两者都可见。",
  "Alpha multiplier applied to the textured faces. 1 = opaque, 0 = invisible. Useful for ghost / holographic looks.": "应用于贴图面的透明度倍率。1 = 不透明，0 = 不可见。适用于幽灵/全息效果。",
  "Alpha multiplier applied to the textured surface. 1 = opaque, 0 = invisible. Useful for ghost / holographic looks.": "应用于贴图表面的透明度倍率。1 = 不透明，0 = 不可见。适用于幽灵/全息效果。",
  "Also create Linux AppImage": "同时生成 Linux AppImage",
  "Always Dash": "始终奔跑",
  "Analog-TV snow / dead-channel noise. Configurable grain size, change speed, contrast, optional color tint, CRT scanlines, and border. Drop it over an LCARS or any panel for \"system offline\" / glitch effects.": "模拟电视雪花/无信号频道噪点。可配置颗粒大小、变化速度、对比度、可选色调、CRT 扫描线和边框。叠加到 LCARS 或任何面板上，可营造“系统离线”/故障效果。",
  "Analyzed {size}.": "已分析 {size}。",
  "Analyzing {file}...": "正在分析 {file}...",
  "Ancient solar/auspicious symbol (Hindu, Buddhist, Jain, Norse, Native American). Defaults to the Eastern upright orientation. Use bendDirection to flip between right-facing (卐) and left-facing (卍).": "古老的太阳/吉祥符号（印度教、佛教、耆那教、北欧、美洲原住民）。默认采用东方的正向姿态。使用 bendDirection 在右旋（卐）和左旋（卍）之间切换。",
  "Angle (degrees below horizontal) of the two lower diagonals. 45° is the classic.": "两条下方对角线与水平线的夹角（度）。45° 为经典值。",
  "Angular extent of each wisp as a fraction of its great circle. 0.5 = each wisp covers half a circumference; 1.0 = full ring.": "每条光丝在其大圆上的角度范围。0.5 = 每条光丝覆盖半圆周长；1.0 = 完整圆环。",
  "Angular spread of the comet tail (±half the spread is added to the trail direction). 0.15 = tight pencil trail; 1.0 = full 180° fan.": "彗尾的角度扩散（扩散的一半加在轨迹方向上）。0.15 = 紧密的铅笔状轨迹；1.0 = 完整的 180° 扇形。",
  "Angular width of each blade. 60° = classic trefoil with equal gaps.": "每个叶片的角宽度。60° = 等间距的经典三叶形。",
  "Angular width of each ray as a fraction of its slot (1 = rays touch, 0 = invisible).": "每条光线的角宽度占其槽位的比例（1 = 光线相接，0 = 不可见）。",
  "Angular width of the rotating sweep wedge. 20° = thin laser, 90° = quarter-disc wash.": "旋转扫描楔形的角宽度。20° = 细激光束，90° = 四分之一圆盘扫掠。",
  "Animated Water": "动态水",
  "Animated sci-fi console panel with bar graphs, oscilloscope, scrolling text rows, blinking status indicators, and progress bar. Wide slider ranges produce everything from minimal terminal to dense data dashboard.": "动态科幻控制台面板，包含条形图、示波器、滚动文本行、闪烁状态指示器和进度条。宽滑块范围可产生从极简终端到密集数据仪表盘的各种效果。",
  "Animated targeting reticle. Brackets snap inward to acquire the target, then pulse when locked. Optional rotating scan lines + jittery center.": "动态瞄准准星。锁定目标时括号向内收缩，锁定后脉动。可选的旋转扫描线和抖动中心。",
  "Any unsaved changes will be lost.": "所有未保存的更改都将丢失。",
  "App root:": "应用根目录：",
  "Approximate character count per text row (more = denser data).": "每行文本的大致字符数（越多 = 数据越密集）。",
