  "Circular radar with rotating sweep line + range rings + blips that fade after the sweep passes. Hostile contacts in enemy color.": "环形雷达，带旋转扫描线、距离环，以及扫描过后淡出的光点。敌对目标以敌人颜色显示。",
  "Classic 3D egg — wider rounded bottom, tapered top. Wireframe lat/lon mesh with full 3D rotation + texturing.": "经典 3D 蛋形——底部宽圆，顶部收窄。经纬线框网格，支持完整的 3D 旋转 + 贴图。",
  "Classic Plugin Command (MV-style text command)": "经典插件指令（MV 风格文本指令）",
  "Classic spinning hypnosis spiral — alternating bands of colour curling outward from the centre. Tune Stripe Count for chunkier/finer bands and Spirality for circles → tight spiral.": "经典旋转催眠螺旋——交替色带从中心向外卷曲。调整条纹数以获得更粗/更细的色带，调整螺旋度可从圆环变为紧密螺旋。",
  "Classic ❤ shape from the parametric heart curve. Full 3D rotation, pulse, optional outer ring + fill + glow.": "由参数化爱心曲线生成的经典 ❤ 形状。完整的 3D 旋转、脉动，可选外环 + 填充 + 发光。",
