  "Dense grid of pseudo-hex bytes with row offsets and hot-byte highlights. Classic memory inspector look.": "密集的伪十六进制字节网格，带行偏移和热点字节高亮。经典内存查看器外观。",
  "Density of horizontal data-fragment arcs painted inside the column. 0 = no overlay.": "柱内绘制水平数据碎片弧的密度。0 = 无叠加。",
  "Direct spatial length of the tail in local units, added to whatever path-history extension comes from Tail Duration. Use this to lengthen tails when the head is stationary (Orbit Speed = 0) or to extend orbiting tails further than the path arc reaches.": "尾部在局部单位下的直接空间长度，叠加在尾部时长带来的路径历史延伸之上。当头部静止（轨道速度 = 0）时可用于加长尾部，或将轨道尾部延伸到路径弧线之外。",
  "Direction Fix OFF": "固定朝向 OFF",
  "Direction Fix ON": "固定朝向 ON",
  "Direction of particle drift. Positive = up, negative = down. Use up for \"beam-up\", down for \"beam-down\".": "粒子漂移方向。正值 = 向上，负值 = 向下。向上用于“光束上升”，向下用于“光束下降”。",
  "Direction the tail points when Orbit Speed = 0. 0° = head with tail pointing left; 90° = tail down; 180° = tail right; 270° = tail up.": "轨道速度为 0 时尾部的指向。0° = 头部带尾部朝左；90° = 尾部朝下；180° = 尾部朝右；270° = 尾部朝上。",
  "Directional energy beam (Kamehameha, ki blast, plasma ray). Tapered shape, wave distortion, source charge, tip burst, particle trail. Loop-safe integer cycles.": "定向能量光束（龟派气功、气功波、等离子射线）。锥形轮廓、波形扭曲、源头充能、尖端爆发、粒子尾迹。循环安全的整数周期。",
