  "Game messages and option labels. %1, %2, %3 are placeholders the engine fills in at runtime (e.g. \"%1 took %2 damage!\" → \"Harold took 25 damage!\"). The hint under each field shows what each placeholder becomes.": "游戏消息和选项标签。%1、%2、%3 是引擎在运行时填充的占位符（例如“%1 受到了 %2 点伤害！”→“哈罗德受到了 25 点伤害！”）。每个字段下方的提示显示每个占位符会被替换为什么。",
