  "Glowing orb of energy (Spirit Bomb, ki sphere, plasma ball). Multi-layer halo + core, surface lightning arcs, orbiting sparkles, optional radial rays.": "发光能量球（元气弹、气功球、等离子球）。多层光晕 + 核心、表面闪电弧、环绕闪光，可选径向光线。",
  "Gray:": "灰色：",
  "Grim-reaper scythe — vertical snath with a long horizontal tapered blade sweeping leftward to a razor point.": "死神镰刀——竖直长柄配水平长锥形刀刃，向左延伸至锋利尖端。",
