  "Irregular faceted 3D rock — low-poly sphere with per-vertex random radius perturbation. Full 3D rotation + texturing.": "不规则多面 3D 岩石——低多边形球体，每个顶点有随机半径扰动。完整的 3D 旋转 + 贴图。",
