  "No {part} selected": "未选择{part}",
  "Nodes connected by edges with light pulses traveling along them. Choose ring or grid topology. Edges generated deterministically.": "节点通过边连接，光脉冲沿边传播。选择环形或网格拓扑。边是确定性生成的。",
  "Noise burst with a slow filter sweep down.": "噪声爆发，带缓慢下扫的滤波器。",
