  "Probability of optional cross-chord (ring) or distance-link (grid) edges. Ring topology always includes neighbor edges.": "可选交叉弦（环形）或距离连接（网格）边的概率。环形拓扑始终包含相邻边。",
  "Procedural / Outfit / Hair Forge parts are JS templates and appear on the Procedural tab, not here.": "程序化/服装/头发锻造部件是 JS 模板，显示在“程序化”标签页中，而不是这里。",
  "Procedural hair aligned to the active body head and eye-line anchors, with frame-aware walk bobbing.": "程序化头发，对齐当前身体头部和眼线锚点，带有感知帧的行走晃动。",
  "Procedural rising flame — particles rise from a base, fade hot-core to cool-tip, with adjustable turbulence and flicker.": "程序化上升火焰——粒子从基底上升，从炽热核心渐变为冷色尖端，湍流和闪烁可调。",
  "Procedural snowflake crystal with animated branching arms, ice-shimmer sparkles, and a rotating inner hexagon.": "程序化雪花晶体，带动画分支臂、冰晶闪光和旋转内六边形。",
