  "Pure sine, immediate attack, long ringing decay.": "纯正弦波，立即起音，长振铃衰减。",
  "Q at the lowpass cutoff. Higher = sharper resonant peak (synth laser). 1 = flat rolloff.": "低通截止处的 Q 值。越高 = 共振峰越尖锐（合成器激光音）。1 = 平直滚降。",
