  "RPG Reactor Web could not start: {error}": "RPG Reactor Web 无法启动：{error}",
  "Radial explosion burst with hot core flash, expanding shockwave ring, debris particles, and smoke dissipation.": "径向爆炸爆发，带炽热核心闪光、扩张的冲击波环、碎片粒子和烟雾消散。",
  "Radial perturbation amount for the wispy curves — how much they bulge in/out from the mean radius.": "光丝曲线的径向扰动量——它们从平均半径内外凸出的程度。",
  "Radial rays from a glowing core with optional rotation + pulse. Holy bursts, sunbeams, lens flares, beacons.": "来自发光核心的径向光线，可选旋转 + 脉动。圣光爆发、阳光、镜头光晕、信标。",
  "Radial thickness of the ring annulus (outer − inner radius).": "圆环的径向厚度（外半径 − 内半径）。",
  "Radius at the narrow base/tip (fraction of half-frame). Classic tornado has this much smaller than top.": "窄底/尖端的半径（半帧的比例）。经典龙卷风此处远小于顶部。",
  "Radius at the wide top of the funnel (fraction of half-frame). Set smaller than base for inverted/drain vortex.": "漏斗宽顶部的半径（半帧的比例）。设置比底部小可得到倒置/排水漩涡。",
  "Radius multiplier for the central glow disc.": "中央辉光圆盘的半径倍率。",
  "Radius of the central disc (fraction of outer radius).": "中央圆盘半径（外半径的比例）。",
  "Radius of the central glow as a fraction of the disc radius.": "中央辉光半径为圆盘半径的比例。",
  "Radius of the portal disc as a fraction of the size. Smaller = tighter portal.": "传送门圆盘半径为整体尺寸的比例。越小 = 传送门越紧凑。",
  "Radius of the spherical bubble in local units. Smaller = tighter shield.": "球形气泡的半径（局部单位）。越小 = 护盾越紧凑。",
  "Rainbow-colored energy tendrils emanating from a central bright point. Each wisp is a tapered curving tendril with halo/body/core lighting. Spread, count, length, wobble, and rainbow rotation are all tunable.": "从中央亮点发出的彩虹色能量触须。每条光丝都是带光晕/主体/核心光照的锥形弯曲触须。扩散、数量、长度、摆动和彩虹旋转均可调。",
