  "Silhouette portrait of Donald Trump, sampled from an SVG path into a polyline. Full 3D rotation, fill, and glow.": "唐纳德·特朗普的剪影肖像，从 SVG 路径采样为折线。完整的 3D 旋转、填充和发光。",
  "Silver": "银色",
  "Sin-wobble of the outline. 0 = clean sphere, 1 = roiling surface.": "轮廓的正弦摆动。0 = 干净球体，1 = 翻涌表面。",
  "Single Preview": "单帧预览",
  "Single archive with all 3 platform runtimes included": "包含全部 3 个平台运行时的单一压缩包",
  "Single sprite detected. Paste these rows into a registered body sheet frame, then hand-clean any pixels where color-only quantizing picked the wrong material.": "检测到单张精灵。将这些行粘贴到已注册的身体图集帧中，然后手动清理纯色量化选错材质的像素。",
  "Size multiplier for the highlight sparks.": "高亮火花的尺寸倍率。",
  "Size multiplier for the internal flame sparkles.": "内部火焰闪光的尺寸倍率。",
  "Size multiplier for the particle dots.": "粒子点的尺寸倍率。",
  "Size multiplier for the rising ember sparks.": "上升余烬火花的尺寸倍率。",
  "Size of each orbiting sparkle.": "每个环绕闪光的大小。",
  "Size of the 4-point star (relative to USSF spec). 0 hides it.": "四角星的大小（相对 USSF 规格）。0 隐藏它。",
  "Size of the 5-point star (relative). 0 hides the star.": "五角星的大小（相对值）。0 隐藏星星。",
  "Size of the bright central core (0 = no core, 0.3 = large bright bloom).": "明亮中央核心的大小（0 = 无核心，0.3 = 大而亮的辉光）。",
  "Size of the central black void (fraction of half-frame).": "中央黑色虚空的大小（半帧的比例）。",
  "Size of the compass rose in the top-left corner. 0 hides it.": "左上角罗盘的尺寸。0 隐藏它。",
  "Size pulsation amount (sin wave). 0 = no pulse, 1 = ±25% size oscillation.": "尺寸脉动幅度（正弦波）。0 = 无脉动，1 = ±25% 尺寸振荡。",
  "Size pulsation frequency (integer cycles per loop).": "尺寸脉动频率（每循环整数周期）。",
