  "Tip: Use proper JavaScript syntax. Common objects: $gameVariables, $gameSwitches, $gameParty, $gameActors": "提示：使用正确的 JavaScript 语法。常用对象：$gameVariables、$gameSwitches、$gameParty、$gameActors",
