  "Top-down strategic display: grid + compass + units moving along parametric trajectories with fading trails. Hostile units pulse with warning rings.": "俯视战略显示：网格 + 罗盘 + 沿参数轨迹移动并带渐隐拖尾的单位。敌对单位以警示环脉动。",
