  "Value Type:": "数值类型：",
  "Values lerp linearly between keyframes — pick a different KF chip in the layer card to edit a different pose.": "数值在关键帧之间线性插值——在图层卡片中选择不同的关键帧芯片可编辑不同的姿态。",
